import{_ as t,o as a,c as o,a0 as d}from"./chunks/framework.l1I-fhud.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),r={name:"explanation/architecture.md"};function c(s,e,n,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><blockquote><p>Seeded from a copy of <code>cuora</code> (its ports-and-adapters anatomy and the <code>-cf</code> Worker pattern).</p></blockquote><p>tamias is <strong>ports-and-adapters</strong>. The engine owns the generic half of distribution; every content <em>meaning</em> is an adapter.</p><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Role</th><th>Impls</th></tr></thead><tbody><tr><td><code>ref</code></td><td>claims + parses a ref into an opaque spec</td><td>one per kind (in the <code>source-*</code> crates)</td></tr><tr><td><code>source</code></td><td><code>plan(spec)</code> → <code>fetch(plan, into)</code></td><td><code>-fs</code>, <code>-git</code>, <code>-http</code>, <code>-cf</code></td></tr><tr><td><code>store</code></td><td>put/get/verify an installed package</td><td><code>-local</code>, <code>-cf</code></td></tr><tr><td><code>cache</code></td><td>content-addressed fetch cache</td><td><code>-local</code>, <code>-cf</code></td></tr><tr><td><code>registry</code></td><td>index + publish</td><td><code>-local</code>, <code>-cf</code> (Worker + R2 + D1/KV)</td></tr><tr><td><code>deploy</code></td><td>service unit + teardown</td><td><code>-local</code> (systemd)</td></tr><tr><td><code>driver</code></td><td>how a content <em>type</em> installs/deploys</td><td><code>tamias-driver-&lt;type&gt;</code> (subprocess, JSON)</td></tr></tbody></table><h2 id="the-install-path" tabindex="-1">The install path <a class="header-anchor" href="#the-install-path" aria-label="Permalink to &quot;The install path&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ref ─► resolve ─► (cache hit?) ─► fetch ─► overlay (include:) ─► driver install ─► store</span></span></code></pre></div><p><code>resolve</code> pins git refs to a commit sha up front, so the content- addressed cache can be hit <em>before</em> fetching. The fetch→unpack split is what makes repeat installs and air-gapped nodes free.</p><h2 id="stores" tabindex="-1">Stores <a class="header-anchor" href="#stores" aria-label="Permalink to &quot;Stores&quot;">​</a></h2><ul><li><strong>install store</strong> — <code>&lt;name&gt;@&lt;version&gt;/</code> with a record (source ref, resolved sha, payload digest, installed-at).</li><li><strong>fetch cache</strong> — content-addressed; <code>remove</code> never touches it.</li><li><strong>registry</strong> — where published content lives: a directory, or a Cloudflare Worker + R2 + D1/KV.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to &quot;Provenance&quot;">​</a></h2><p><code>verify</code> recomputes the payload digest against the record. Digest-pinned refs (<code>#sha256:…</code>, resolved shas) are the integrity contract.</p>',12)])])}const f=t(r,[["render",c]]);export{u as __pageData,f as default};
